#include <bits/stdc++.h>
using namespace std;

struct Rect {
    int w, h;
    Rect(int w, int h) : w(w), h(h) {}
    int area() const { return w * h; }
    int perimeter() const { return 2 * (w + h); }
    bool isSquare() const { return w == h; }
    bool biggerThan(const Rect& o) const { return area() > o.area(); }
    void scale(int k) { w *= k; h *= k; }
};

int totalArea(const vector<Rect>& v) {
    int s = 0;
    for (const auto& r : v) s += r.area();
    return s;
}

int main() {
    vector<Rect> v;
    v.push_back(Rect(3, 4));
    v.push_back(Rect(5, 5));
    v.push_back(Rect(2, 9));
    v[0].scale(2);
    for (const auto& r : v) {
        cout << r.w << "x" << r.h << " area=" << r.area() << " per=" << r.perimeter();
        if (r.isSquare()) cout << " square";
        cout << "\n";
    }
    cout << "total=" << totalArea(v) << "\n";
    cout << (v[0].biggerThan(v[1]) ? "first bigger" : "second bigger") << "\n";
    const Rect c(7, 1);
    cout << c.area() + c.perimeter() << "\n";
    return 0;
}

