class BankAccount {
private:
    string owner;
    double balance;
    int txCount;
public:
    BankAccount(string owner, double balance) {
        this->owner = owner;
        this->balance = balance;
        this->txCount = 0;
    }
    string getOwner() const { return owner; }
    double getBalance() const { return balance; }
    int getTxCount() const { return txCount; }
    void setOwner(string owner) { this->owner = owner; }
    bool canWithdraw(double amount) const { return amount > 0 && amount <= balance; }
    bool withdraw(double amount) {
        if (!canWithdraw(amount)) return false;
        balance -= amount;
        txCount++;
        return true;
    }
    void deposit(double amount) {
        balance += amount;
        txCount += 1;
    }
    bool transferTo(BankAccount& other, double amount) {
        if (withdraw(amount)) {
            other.deposit(amount);
            return true;
        }
        return false;
    }
};

void report(const BankAccount& a) {
    cout << a.getOwner() << ": " << fixed << setprecision(2) << a.getBalance()
         << " (" << a.getTxCount() << " tx)" << "\n";
}

int main() {
    BankAccount a("Alice", 100.0);
    BankAccount b("Bob", 20.5);
    cout << (a.transferTo(b, 30.25) ? "ok" : "fail") << "\n";
    cout << (b.transferTo(a, 1000) ? "ok" : "fail") << "\n";
    b.setOwner("Robert");
    a.deposit(0.75);
    report(a);
    report(b);
    if (a.getBalance() > b.getBalance() && a.canWithdraw(70)) cout << "Alice richer\n";
    return 0;
}

