struct Student {
    string name;
    int math, eng, sci;
    int total() const { return math + eng + sci; }
    double average() const { return total() / 3.0; }
    bool passed() const { return average() >= 60.0 && min3() >= 40; }
    int min3() const { return min(math, min(eng, sci)); }
    bool operator<(const Student& o) const {
        if (total() != o.total()) return total() > o.total();
        return name < o.name;
    }
};

int main() {
    vector<Student> s = {
        {"Eve", 70, 80, 90},
        {"Bob", 90, 90, 60},
        {"Amy", 30, 100, 95},
        {"Dan", 50, 55, 58},
        {"Cal", 60, 60, 60}
    };
    sort(s.begin(), s.end());
    int rank = 1;
    for (const auto& st : s) {
        cout << rank++ << ". " << st.name << " " << st.total() << " "
             << fixed << setprecision(1) << st.average() << " "
             << (st.passed() ? "PASS" : "FAIL") << "\n";
    }
    sort(s.begin(), s.end(), [](const Student& a, const Student& b) {
        return a.min3() < b.min3();
    });
    cout << "weakest: " << s.front().name << " min=" << s.front().min3() << "\n";
    int cnt = count_if(s.begin(), s.end(), [](const Student& x) { return x.passed(); });
    cout << "passed: " << cnt << "\n";
    return 0;
}

