class Vec2 {
public:
    double x, y;
    Vec2() : x(0), y(0) {}
    Vec2(double x, double y) : x(x), y(y) {}
    double dot(const Vec2& o) const { return x * o.x + y * o.y; }
    double length() const { return sqrt(dot(*this)); }
    Vec2 plus(const Vec2& o) const { return Vec2(x + o.x, y + o.y); }
    Vec2 scaled(double k) const { return Vec2(x * k, y * k); }
    void addInPlace(const Vec2& o) { x += o.x; y += o.y; }
    bool isZero() const { return length() < 1e-9; }
    string str() const {
        ostringstream os;
        os << "(" << x << ", " << y << ")";
        return os.str();
    }
};

class Polygon {
private:
    vector<Vec2> pts;
public:
    void add(double x, double y) { pts.push_back(Vec2(x, y)); }
    int size() const { return (int)pts.size(); }
    double perimeter() const {
        double p = 0;
        for (int i = 0; i < size(); i++) {
            const Vec2& a = pts[i];
            const Vec2& b = pts[(i + 1) % size()];
            p += b.plus(a.scaled(-1)).length();
        }
        return p;
    }
    double area() const {
        double s = 0;
        for (int i = 0; i < size(); i++) {
            int j = (i + 1) % size();
            s += pts[i].x * pts[j].y - pts[j].x * pts[i].y;
        }
        return fabs(s) / 2.0;
    }
    Vec2 centroid() const {
        Vec2 c;
        for (const auto& p : pts) c.addInPlace(p);
        return c.scaled(1.0 / size());
    }
};

int main() {
    Polygon poly;
    poly.add(0, 0);
    poly.add(4, 0);
    poly.add(4, 3);
    poly.add(0, 3);
    cout << "n=" << poly.size() << "\n";
    cout << "perimeter=" << poly.perimeter() << "\n";
    cout << "area=" << poly.area() << "\n";
    cout << "centroid=" << poly.centroid().str() << "\n";
    Vec2 a(3, 4), b(-3, -4);
    cout << a.length() << " " << a.plus(b).isZero() << " " << a.dot(b) << "\n";
    return 0;
}

