class Inventory {
private:
    map<string, int> stock;
    map<string, double> price;
public:
    void addItem(const string& name, int qty, double p) {
        stock[name] += qty;
        price[name] = p;
    }
    bool has(const string& name, int qty) const {
        auto it = stock.find(name);
        return it != stock.end() && it->second >= qty;
    }
    double priceOf(const string& name) const {
        auto it = price.find(name);
        if (it == price.end()) return 0.0;
        return it->second;
    }
    double order(const string& name, int qty, double discount) {
        if (!has(name, qty)) return -1.0;
        stock[name] -= qty;
        double cost = priceOf(name) * qty;
        if (qty >= 10) cost *= (1.0 - discount);
        return cost;
    }
    double totalValue() const {
        double v = 0;
        for (const auto& kv : stock) v += kv.second * priceOf(kv.first);
        return v;
    }
    int countLow(int threshold) const {
        int c = 0;
        for (const auto& kv : stock)
            if (kv.second < threshold) c++;
        return c;
    }
};

int main() {
    Inventory inv;
    inv.addItem("pen", 50, 1.5);
    inv.addItem("book", 5, 12.0);
    inv.addItem("pen", 10, 1.25);
    inv.addItem("eraser", 3, 0.5);
    cout << fixed << setprecision(2);
    cout << inv.order("pen", 20, 0.1) << "\n";
    cout << inv.order("book", 6, 0.1) << "\n";
    cout << inv.order("book", 2, 0.1) << "\n";
    cout << inv.order("glue", 1, 0.0) << "\n";
    cout << "value=" << inv.totalValue() << "\n";
    cout << "low=" << inv.countLow(5) << "\n";
    const Inventory& ref = inv;
    if (ref.has("pen", 40) && !ref.has("pen", 41)) cout << "exactly 40 pens\n";
    return 0;
}

