struct Time {
    int h, m;
    Time(int h = 0, int m = 0) : h(h), m(m) { normalize(); }
    void normalize() {
        h += m / 60;
        m %= 60;
        if (m < 0) { m += 60; h--; }
        h = ((h % 24) + 24) % 24;
    }
    int toMinutes() const { return h * 60 + m; }
    void addMinutes(int d) { m += d; normalize(); }
    bool before(const Time& o) const { return toMinutes() < o.toMinutes(); }
    int diff(const Time& o) const { return o.toMinutes() - toMinutes(); }
    string str() const {
        string s;
        if (h < 10) s += "0";
        s += to_string(h) + ":";
        if (m < 10) s += "0";
        s += to_string(m);
        return s;
    }
};

class Meeting {
    Time start, end_;
    string title;
public:
    Meeting(string title, Time start, int duration) : start(start), end_(start), title(title) {
        end_.addMinutes(duration);
    }
    bool overlaps(const Meeting& o) const {
        return start.before(o.end_) && o.start.before(end_);
    }
    int length() const { return start.diff(end_); }
    const Time& getStart() const { return start; }
    string describe() const { return title + " " + start.str() + "-" + end_.str(); }
};

int main() {
    vector<Meeting> ms;
    ms.push_back(Meeting("Standup", Time(9, 0), 15));
    ms.push_back(Meeting("Review", Time(8, 50), 30));
    ms.push_back(Meeting("Lunch", Time(12, 0), 60));
    ms.push_back(Meeting("Late", Time(23, 30), 45));
    sort(ms.begin(), ms.end(), [](const Meeting& a, const Meeting& b) {
        return a.getStart().before(b.getStart());
    });
    for (const auto& x : ms) cout << x.describe() << " len=" << x.length() << "\n";
    for (size_t i = 0; i < ms.size(); i++)
        for (size_t j = i + 1; j < ms.size(); j++)
            if (ms[i].overlaps(ms[j])) cout << "conflict " << i << " " << j << "\n";
    Time t(1, -30);
    cout << t.str() << " " << Time(25, 125).str() << "\n";
    return 0;
}

