class Matrix {
private:
    int n;
    vector<vector<long long>> a;
public:
    Matrix(int n) : n(n), a(n, vector<long long>(n, 0)) {}
    int size() const { return n; }
    long long get(int r, int c) const { return a[r][c]; }
    void set(int r, int c, long long v) { a[r][c] = v; }
    static Matrix identity(int n) {
        Matrix m(n);
        for (int i = 0; i < n; i++) m.set(i, i, 1);
        return m;
    }
    Matrix multiply(const Matrix& o, long long mod) const {
        Matrix r(n);
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                long long s = 0;
                for (int k = 0; k < n; k++) s = (s + get(i, k) * o.get(k, j)) % mod;
                r.set(i, j, s);
            }
        return r;
    }
    Matrix power(long long e, long long mod) const {
        Matrix result = identity(n);
        Matrix base = *this;
        while (e > 0) {
            if (e & 1) result = result.multiply(base, mod);
            base = base.multiply(base, mod);
            e >>= 1;
        }
        return result;
    }
    long long trace() const {
        long long t = 0;
        for (int i = 0; i < size(); i++) t += get(i, i);
        return t;
    }
    bool isSymmetric() const {
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                if (get(i, j) != get(j, i)) return false;
        return true;
    }
};

void print(const Matrix& m) {
    for (int i = 0; i < m.size(); i++) {
        for (int j = 0; j < m.size(); j++) cout << m.get(i, j) << (j + 1 < m.size() ? " " : "\n");
    }
}

int main() {
    const long long MOD = 1000000007LL;
    Matrix f(2);
    f.set(0, 0, 1); f.set(0, 1, 1); f.set(1, 0, 1);
    Matrix p = f.power(50, MOD);
    cout << "fib50=" << p.get(0, 1) << "\n";
    print(f.power(5, MOD));
    cout << "trace=" << p.trace() % MOD << " sym=" << (p.isSymmetric() ? "yes" : "no") << "\n";
    Matrix g(3);
    g.set(0, 1, 2); g.set(1, 2, 3);
    cout << "sym g=" << g.isSymmetric() << " trace g^3=" << g.power(3, MOD).trace() << "\n";
    return 0;
}

