class Counter {
    int value;
    int step;
    int limit;
public:
    Counter(int value, int step, int limit) : value(value), step(step), limit(limit) {}
    int get() const { return value; }
    bool atLimit() const { return value >= limit; }
    int remaining() const { return atLimit() ? 0 : (limit - value + step - 1) / step; }
    Counter& tick() {
        if (!atLimit()) value += step;
        return *this;
    }
    void setStep(int step) {
        if (step > 0) this->step = step;
    }
    void reset(int value) { this->value = value; }
    string status() const {
        return to_string(get()) + "/" + to_string(limit) + (atLimit() ? " done" : " (" + to_string(remaining()) + " left)");
    }
};

int main() {
    Counter c(0, 3, 10);
    cout << c.status() << "\n";
    c.tick().tick();
    cout << c.status() << "\n";
    c.setStep(-5);
    c.tick();
    cout << c.status() << "\n";
    c.setStep(4);
    while (!c.atLimit()) c.tick();
    cout << c.status() << "\n";
    c.reset(7);
    int loops = 0;
    for (; c.remaining() > 0; loops++) c.tick();
    cout << "loops=" << loops << " final=" << c.get() << "\n";
    vector<Counter> cs = {Counter(1, 1, 3), Counter(5, 2, 4), Counter(0, 10, 25)};
    for (auto& x : cs) x.tick();
    for (const auto& x : cs) cout << x.status() << "\n";
    return 0;
}

