struct Edge {
    int u, v, w;
    bool operator<(const Edge& o) const { return w < o.w || (w == o.w && u < o.u); }
};

class DSU {
private:
    vector<int> parent, sz;
public:
    DSU(int n) : parent(n), sz(n, 1) {
        for (int i = 0; i < n; i++) parent[i] = i;
    }
    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (sz[a] < sz[b]) swap(a, b);
        parent[b] = a;
        sz[a] += sz[b];
        return true;
    }
    bool same(int a, int b) { return find(a) == find(b); }
    int componentSize(int x) { return sz[find(x)]; }
};

class Graph {
    int n;
    vector<Edge> edges;
public:
    Graph(int n) : n(n) {}
    void addEdge(int u, int v, int w) { edges.push_back({u, v, w}); }
    int edgeCount() const { return (int)edges.size(); }
    long long mst(vector<Edge>& used) const {
        vector<Edge> sorted = edges;
        sort(sorted.begin(), sorted.end());
        DSU d(n);
        long long total = 0;
        for (const Edge& e : sorted) {
            if (d.unite(e.u, e.v)) {
                total += e.w;
                used.push_back(e);
            }
        }
        return (int)used.size() == n - 1 ? total : -1;
    }
};

int main() {
    Graph g(5);
    g.addEdge(0, 1, 4);
    g.addEdge(0, 2, 1);
    g.addEdge(1, 2, 2);
    g.addEdge(1, 3, 5);
    g.addEdge(2, 3, 8);
    g.addEdge(3, 4, 3);
    g.addEdge(2, 4, 9);
    vector<Edge> used;
    cout << "edges=" << g.edgeCount() << "\n";
    cout << "mst=" << g.mst(used) << "\n";
    for (const auto& e : used) cout << e.u << "-" << e.v << " " << e.w << "\n";
    Graph h(4);
    h.addEdge(0, 1, 1);
    h.addEdge(2, 3, 1);
    vector<Edge> u2;
    cout << "disconnected=" << h.mst(u2) << "\n";
    DSU d(6);
    d.unite(0, 1); d.unite(2, 3); d.unite(1, 3);
    cout << d.same(0, 2) << " " << d.same(4, 5) << " " << d.componentSize(3) << "\n";
    return 0;
}

