class Fraction {
private:
    long long num, den;
    static long long gcdll(long long a, long long b) { return b == 0 ? a : gcdll(b, a % b); }
    void reduce() {
        if (den < 0) { num = -num; den = -den; }
        long long g = gcdll(llabs(num), den);
        if (g > 1) { num /= g; den /= g; }
    }
public:
    Fraction(long long num = 0, long long den = 1) : num(num), den(den) { reduce(); }
    long long getNum() const { return num; }
    long long getDen() const { return den; }
    Fraction add(const Fraction& o) const { return Fraction(num * o.den + o.num * den, den * o.den); }
    Fraction mul(const Fraction& o) const { return Fraction(num * o.num, den * o.den); }
    Fraction& addAssign(const Fraction& o) {
        num = num * o.den + o.num * den;
        den *= o.den;
        reduce();
        return *this;
    }
    double value() const { return (double)num / den; }
    bool isInteger() const { return den == 1; }
    bool lessThan(const Fraction& o) const { return num * o.den < o.num * den; }
    bool equals(const Fraction& o) const { return !lessThan(o) && !o.lessThan(*this); }
    string str() const { return isInteger() ? to_string(num) : to_string(num) + "/" + to_string(den); }
};

int main() {
    Fraction h(0);
    for (int i = 1; i <= 6; i++) h.addAssign(Fraction(1, i));
    cout << "H6=" << h.str() << " ~ " << fixed << setprecision(4) << h.value() << "\n";
    vector<Fraction> fs = {Fraction(3, -6), Fraction(2, 3), Fraction(-1, 4), Fraction(4, 2), Fraction(5, 7)};
    sort(fs.begin(), fs.end(), [](const Fraction& a, const Fraction& b) { return a.lessThan(b); });
    for (const auto& f : fs) cout << f.str() << (f.isInteger() ? " int" : "") << "\n";
    Fraction a(1, 2), b(2, 4);
    cout << (a.equals(b) ? "equal" : "different") << "\n";
    Fraction p = a.mul(Fraction(4, 3)).add(Fraction(-2, 3));
    cout << p.str() << " " << p.isInteger() << " " << p.getNum() << "/" << p.getDen() << "\n";
    return 0;
}
